<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\Accessor\UserGrantedClientScopesScopeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserGrantedClientScopesScopeAccessor trait.
 *
 * Covers null default, string/VO assignment via withScope,
 * getScope/scope accessors, and isScopeChanged with/without original.
 */
class UserGrantedClientScopesScopeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withScope creates a new instance with the Scope set
     * from a string value, and getScope returns the primitive string.
     */
    public function testWithScopeFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserGrantedClientScopesScopeAccessorUnitTest();

        // Act
        $result = $holder->withScope('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getScope());
    }
    /**
     * Asserts that withscope has access to the value object
     * from a string value, and getScope returns the primitive string.
     */
    public function testWithScopeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserGrantedClientScopesScopeAccessorUnitTest();

        // Act
        $result = $holder->withScope('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->scope()->value());
    }
    public function testChangedScope(): void
    {
        // Arrange
        $holder = new ImplWithUserGrantedClientScopesScopeAccessorUnitTest();
        $original = $holder->withScope('one');
        $same = $holder->withScope('one');
        $modified = $holder->withScope('other');

        // Act
        $unchanged = $holder->isScopeChanged();
        $withSame = $original->isScopeChanged($same);
        $withDiferent = $original->isScopeChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserGrantedClientScopesScopeAccessorUnitTest
{
    use UserGrantedClientScopesScopeAccessor;
}
